head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > js]<br/>여러 개의 외부 JavaScript 파일을 병렬로 로딩하면서 실행은 인자 순서대로 순차 실행합니다.",
    "validation" : [
        "Url(필수) 파라미터로 로드할 JavaScript 파일의 URL 을 설정할 수 있어야 합니다.",
        "여러 개의 외부 JavaScript 파일을 병렬로 로딩하면서 실행은 인자 순서대로 순차 실행해야 합니다.",
        "callback(선택) 파라미터로 모든 스크립트 실행 완료 후 실행할 콜백 함수를 설정할 수 있어야 합니다.",
        "callback 파라미터를 생략하면 콜백 없이 스크립트만 순차 실행해야 합니다.",
        "가변 인자의 마지막 인자가 Function 인 경우에만 콜백으로 동작해야 합니다.",
        "WebSquare.util 객체를 반환하여 메소드 체이닝이 가능해야 합니다.",
        "로드한 스크립트는 전역 Scope 에서 실행되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 초기화: 전역 변수 리셋
scwin.resetGlobal = function () {
    window.__jsLoadOrder = [];
    window.__callbackExecuted = false;
}



scwin.btn_jsWithCallback_onclick = function () {
    scwin.resetGlobal();

    WebSquare.util.js(
        "/js/util_js_1_seq1.js",
        "/js/util_js_1_seq2.js",
        "/js/util_js_1_seq3.js",
        function () {
            window.__callbackExecuted = true;
            wf_body_bottom.getObj("scwin").setReturnValue(
                "실행 순서 : " + window.__jsLoadOrder.join(",") + "\n" +
                "콜백 실행 : " + window.__callbackExecuted
            );
        }
    );
}



scwin.btn_jsWithoutCallback_onclick = function () {
    window.__jsLoadOrder2 = [];

    WebSquare.util.js(
        "/js/util_js_1_nocb1.js",
        "/js/util_js_1_nocb2.js",
        "/js/util_js_1_nocb3.js"
    );

    // 콜백 없이 실행되므로 일정 시간 후 결과를 확인
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue(
            "실행 순서 : " + window.__jsLoadOrder2.join(",") + "\n" +
            "콜백 실행 : false"
        );
    }, 2000);
}



scwin.btn_jsChaining_onclick = function () {
    let ret = WebSquare.util.js("/js/util_js_1_chain.js", function () {});
    let isUtil = (ret === WebSquare.util);
    wf_body_bottom.getObj("scwin").setReturnValue("메소드 체이닝 가능 : " + isUtil);
}



scwin.btn_jsGlobalScope_onclick = function () {
    window.__globalScopeTest2 = undefined;

    WebSquare.util.js(
        "/js/util_js_1_global.js",
        function () {
            let exists = (window.__globalScopeTest2 === "loaded");
            wf_body_bottom.getObj("scwin").setReturnValue("전역 Scope 실행 : " + exists);
        }
    );
}
